The problem of reversing a singly linked list can be solved using several approaches, including iterative and recursive methods. Below are some solutions in different programming languages:

**Iterative Method**

*   C++
    ```c
Node *reverseList(Node *head) {
    Node *curr = head;
    Node *prev = nullptr;

    while (curr != nullptr) {
        Node *next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}
```

*   Java
    ```java
Node reverseList(Node head) {
    Node curr = head;
    Node prev = null;

    while (curr != null) {
        Node next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}
```

*   Python
    ```python
def reverseList(head):
    curr = head
    prev = None

    while curr is not None:
        next_node = curr.next
        curr.next = prev
        prev = curr
        curr = next_node
    return prev
```

**Recursive Method**

*   C++
    ```c
Node *reverseList(Node *head) {
    if (head == nullptr || head->next == nullptr)
        return head;
    Node *rest = reverseList(head->next);
    head->next->next = head;
    head->next = nullptr;
    return rest;
}
```

*   Java
    ```java
Node reverseList(Node head) {
    if (head == null || head.next == null)
        return head;
    Node rest = reverseList(head.next);
    head.next.next = head;
    head.next = null;
    return rest;
}
```

*   Python
    ```python
def reverseList(head):
    if not head or not head.next:
        return head

    def recursiveReverse(node):
        if node is None:
            return None, None

        new_head, tail = recursiveReverse(node.next)
        tail.next = node
        node.next = None
        return node, node

    new_head, _ = recursiveReverse(head)
    return new_head
```

These solutions demonstrate how to reverse a singly linked list using both iterative and recursive approaches. The chosen solution will depend on the specific requirements of the task and personal preference for coding style.

class Solution:
    class ListNode:
        def __init__(self, value=0, next=None):
            self.value = value
            self.next = next

    def solve(self, head):
        prev = None
        current = head
        while current is not None:
            next_node = current.next
            current.next = prev
            prev = current
            current = next_node
